import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function CartPage(){
  const [cart, setCart] = useState([]);
  const navigate = useNavigate();

  useEffect(()=> { setCart(JSON.parse(localStorage.getItem('cart')||'[]')); }, []);

  function updateQty(i, delta){
    const c = [...cart];
    c[i].qty = Math.max(1, c[i].qty + delta);
    setCart(c);
    localStorage.setItem('cart', JSON.stringify(c));
  }

  function removeItem(i){
    const c = cart.filter((_,idx)=>idx!==i);
    setCart(c); localStorage.setItem('cart', JSON.stringify(c));
  }

  const total = cart.reduce((s,it)=>s + (it.price * it.qty), 0);

  return (
    <div>
      <h2 className="text-2xl font-bold mb-4">Your Cart</h2>
      {cart.length===0 ? <div>Your cart is empty</div> : (
        <div className="space-y-4">
          {cart.map((it,idx)=>(
            <div key={idx} className="flex items-center gap-4 bg-white p-3 rounded shadow">
              <img src={it.coverUrl || 'https://via.placeholder.com/120x160'} className="w-24 h-32 object-cover" alt="" />
              <div className="flex-1">
                <div className="font-semibold">{it.title}</div>
                <div className="text-gray-500">Rs {it.price}</div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={()=>updateQty(idx,-1)} className="px-2 py-1 border rounded">-</button>
                <span>{it.qty}</span>
                <button onClick={()=>updateQty(idx,1)} className="px-2 py-1 border rounded">+</button>
                <button onClick={()=>removeItem(idx)} className="ml-4 text-red-600">Remove</button>
              </div>
            </div>
          ))}
          <div className="text-right font-bold">Total: Rs {total}</div>
          <div className="flex justify-end gap-3">
            <button onClick={()=>navigate('/checkout')} className="bg-blue-600 text-white px-4 py-2 rounded">Proceed to Checkout</button>
          </div>
        </div>
      )}
    </div>
  );
}
